from full_a import cat, C

cat("beginning", "In the Beginning", "The first families in Genesis.", "creation-light", [
 dict(id="adam-eve", name="Adam & Eve", role="The first man and woman", art="eden",
  facts=["Made by God", "Lived in the Garden of Eden", "Parents of Cain, Abel and Seth"], cards=[
  C("Made by God", "God formed Adam from the dust of the ground and breathed life into him. Then He made Eve from Adam’s side.",
    "“Adam” is the Hebrew word for human, related to adamah, ground. God placed him in Eden to work the garden and take care of it, and had him name the animals. None was a fitting partner, so God put Adam into a deep sleep and formed a woman from his rib. Adam said, “This is now bone of my bones and flesh of my flesh.” Eve’s name means “living,” because she would be the mother of all the living. They were naked and felt no shame.", ("Genesis",2)),
  C("One rule", "They could eat from every tree except the tree of the knowledge of good and evil.",
    "God said, “You are free to eat from any tree in the garden; but you must not eat from the tree of the knowledge of good and evil, for when you eat from it you will certainly die.” Everything else was theirs, including the tree of life.", ("Genesis",2)),
  C("The serpent", "A serpent asked Eve, “Did God really say…?” and told her she wouldn’t die — she’d be like God. She ate, and gave some to Adam.",
    "The serpent twisted God’s words, then contradicted them. Eve saw the fruit was good for food, pleasing to the eye, and desirable for gaining wisdom. Adam was with her, and he ate too. Their eyes were opened; they realized they were naked and sewed fig leaves together.", ("Genesis",3)),
  C("Hiding from God", "When God walked in the garden, they hid. Adam blamed Eve; Eve blamed the serpent.",
    "God called, “Where are you?” Adam said he was afraid because he was naked. God asked if he had eaten from the tree. Adam said, “The woman You put here with me — she gave me some.” Eve said, “The serpent deceived me.” God announced the consequences: pain in childbirth, struggle in work, and death — “for dust you are and to dust you will return.” But to the serpent He promised that a descendant of the woman would crush its head — the first promise of a Savior.", ("Genesis",3)),
  C("Out of Eden", "God made them clothes from animal skins and sent them out of the garden. Cherubim with a flaming sword guarded the way back.",
    "They lost access to the tree of life. Outside Eden they had sons — Cain, Abel and later Seth — and other sons and daughters. The Bible says Adam lived 930 years. Paul later calls Jesus “the last Adam,” who succeeded where the first failed.", ("Genesis",3)),
 ]),
 dict(id="cain-abel", name="Cain & Abel", role="The first brothers — and the first murder", art="cain-abel",
  facts=["Sons of Adam & Eve", "A farmer and a shepherd", "Jealousy turned deadly"], cards=[
  C("Two brothers, two offerings", "Cain farmed and Abel kept sheep. God accepted Abel’s offering — the best of his flock — but not Cain’s.",
    "Abel brought fat portions from the firstborn of his flock; Cain brought “some of the fruits.” Hebrews says Abel offered by faith. Cain became very angry and his face was downcast.", ("Genesis",4)),
  C("Sin at the door", "God warned Cain: “Sin is crouching at your door; it desires to have you, but you must rule over it.”",
    "God asked why he was angry and told him that if he did what was right, he would be accepted. It was a chance to turn around.", ("Genesis",4)),
  C("“Am I my brother’s keeper?”", "Cain lured Abel into a field and killed him. When God asked where Abel was, Cain lied.",
    "God said, “Your brother’s blood cries out to Me from the ground.” Cain was sentenced to be a restless wanderer. He protested that anyone would kill him, so God put a mark on him so no one would. Cain settled east of Eden in the land of Nod and built a city. Adam and Eve later had Seth, through whom Noah’s line came.", ("Genesis",4)),
 ]),
 dict(id="noah", name="Noah", role="The man who built the ark", art="flood",
  facts=["Built a giant boat", "Rain for 40 days", "God’s rainbow promise"], cards=[
  C("A violent world", "The earth had become full of violence. But Noah was righteous and walked faithfully with God.",
    "God saw that every inclination of human hearts was only evil all the time, and it grieved Him. “But Noah found favor in the eyes of the Lord.” He had three sons: Shem, Ham and Japheth.", ("Genesis",6)),
  C("Build an ark", "God told Noah to build an ark about 450 feet long and fill it with his family and pairs of every kind of animal.",
    "The ark was 300 cubits long, 50 wide and 30 high — three decks, coated with pitch inside and out. It likely took decades to build. Noah did everything just as God commanded.", ("Genesis",6)),
  C("The flood", "Rain fell 40 days and nights. The water covered even the mountains, and everything outside the ark died.",
    "Noah was 600 years old. God Himself shut the door. The springs of the deep burst open and the floodgates of heaven opened. The waters flooded the earth for 150 days.", ("Genesis",7)),
  C("The dove", "As the water went down, Noah sent out a raven, then a dove. The dove came back with an olive leaf.",
    "The ark came to rest on the mountains of Ararat. The second time the dove came back in the evening with a freshly plucked olive leaf. A week later it didn’t come back at all. Noah’s family had been in the ark over a year.", ("Genesis",8)),
  C("The rainbow", "Noah built an altar. God promised never again to destroy the earth by flood, and set His rainbow in the clouds as the sign.",
    "God blessed Noah and his sons: “Be fruitful and increase in number and fill the earth.” Every nation, Genesis says, descends from Noah’s three sons. Later Noah planted a vineyard, got drunk, and his son Ham dishonored him — even heroes of faith were flawed. Noah lived 950 years.", ("Genesis",9)),
 ]),
 dict(id="abraham", name="Abraham", role="Father of faith", art="three-angels",
  facts=["Left home at 75", "Had a son at 100", "Father of many nations"], cards=[
  C("Go", "God told Abram, age 75, to leave his country and family for a land He would show him. Abram went.",
    "God promised: “I will make you into a great nation… and all peoples on earth will be blessed through you.” Abram took his wife Sarai, his nephew Lot and everything they owned to Canaan, without knowing where he was going.", ("Genesis",12)),
  C("Count the stars", "Childless and old, Abram asked God about the promise. God took him outside: “Count the stars. So shall your offspring be.”",
    "“Abram believed the Lord, and He credited it to him as righteousness.” God made a covenant with him in a strange ceremony, passing between cut animals as a smoking firepot and blazing torch — God taking the oath on Himself.", ("Genesis",15)),
  C("Hagar and Ishmael", "Tired of waiting, Sarai gave her servant Hagar to Abram. Hagar had a son, Ishmael — and the household filled with tension.",
    "Abram was 86. Hagar began to despise Sarai, and Sarai mistreated her until she ran away. An angel found her by a spring and sent her back with a promise for her son. God later promised Ishmael would also become a great nation.", ("Genesis",16)),
  C("A new name", "When Abram was 99, God renamed him Abraham — “father of many” — and Sarai became Sarah. Circumcision became the covenant sign.",
    "God promised that Sarah herself would have a son within a year. Abraham fell facedown laughing at the idea of a 100-year-old and a 90-year-old having a baby.", ("Genesis",17)),
  C("Pleading for Sodom", "Abraham bargained with God to spare Sodom if 50 righteous people lived there — then 45, 30, 20, finally 10.",
    "“Will not the Judge of all the earth do right?” God agreed each time. Ten righteous people could not be found, but God rescued Abraham’s nephew Lot before destroying the city.", ("Genesis",18)),
  C("Isaac is born", "At 100, Abraham finally held his promised son, Isaac.",
    "Sarah said, “God has brought me laughter, and everyone who hears about this will laugh with me.” Isaac means “he laughs.”", ("Genesis",21)),
  C("The test", "God told Abraham to sacrifice Isaac on Mount Moriah. Abraham obeyed — and an angel stopped him at the last moment. God provided a ram.",
    "Isaac asked, “Where is the lamb?” Abraham answered, “God Himself will provide the lamb.” He bound Isaac on the altar and raised the knife. The angel called, “Do not lay a hand on the boy.” Abraham named the place “The Lord Will Provide.” Hebrews says Abraham reasoned that God could raise the dead. Mount Moriah is where Solomon later built the Temple in Jerusalem.", ("Genesis",22)),
  C("His legacy", "Abraham died at 175. Jews, Christians and Muslims all trace their faith back to him.",
    "He bought a cave at Machpelah in Hebron to bury Sarah — his only land in the promised country — and was buried there too. The New Testament calls him the father of all who believe.", ("Genesis",25)),
 ]),
 dict(id="sarah", name="Sarah", role="The woman who laughed — and then had a baby at 90", art="three-angels",
  facts=["Abraham’s wife", "Mother of Isaac", "Name means “princess”"], cards=[
  C("Beautiful and barren", "Sarai left everything with Abram at 65. She was so beautiful that Abram twice passed her off as his sister to protect himself.",
    "In Egypt and later in Gerar, kings took her into their households until God intervened. She was also Abram’s half-sister, so it was a half-truth.", ("Genesis",12)),
  C("Taking control", "Childless for decades, Sarai gave her servant Hagar to Abram. When Hagar got pregnant, there was bitter conflict.",
    "It was a legal custom of the time, but it brought pain to everyone involved.", ("Genesis",16)),
  C("She laughed", "Overhearing the Lord promise she’d have a son within a year, 89-year-old Sarah laughed. God asked, “Is anything too hard for the Lord?”",
    "Afraid, she denied it: “I did not laugh.” The Lord said, “Yes, you did.”", ("Genesis",18)),
  C("Laughter", "A year later Sarah gave birth to Isaac. “God has brought me laughter.”",
    "She died at 127 in Hebron, the only woman whose age at death is recorded in the Bible. Hebrews lists her among the heroes of faith.", ("Genesis",21)),
 ]),
 dict(id="jacob", name="Jacob", role="The schemer God renamed Israel", art="jacob-wrestles",
  facts=["Twin of Esau", "Father of 12 sons", "The 12 tribes come from him"], cards=[
  C("Grabbing the heel", "Jacob was born holding his twin brother Esau’s heel. His name roughly means “he grabs.”",
    "Even before they were born, God told Rebekah the older would serve the younger. Esau became a hunter, Isaac’s favorite; Jacob stayed among the tents, Rebekah’s favorite.", ("Genesis",25)),
  C("Stew for a birthright", "Esau came home starving. Jacob traded him a bowl of red stew for his rights as firstborn.",
    "The birthright meant a double inheritance and family leadership. Esau said, “I’m about to die — what good is a birthright to me?” He ate, drank and left, despising it.", ("Genesis",25)),
  C("The stolen blessing", "With his mother’s help, Jacob dressed in goatskins to fool blind Isaac and stole Esau’s blessing.",
    "Isaac said, “The voice is the voice of Jacob, but the hands are the hands of Esau.” When Esau found out, he wept bitterly and vowed to kill Jacob. Jacob fled to his uncle Laban.", ("Genesis",27)),
  C("A ladder to heaven", "Sleeping on a stone, Jacob dreamed of a stairway with angels and heard God promise to be with him.",
    "He woke up and said, “Surely the Lord is in this place, and I was not aware of it.” He named the place Bethel, “house of God.”", ("Genesis",28)),
  C("The trickster tricked", "Jacob worked seven years to marry Rachel. On the wedding night, Laban switched in her sister Leah.",
    "Jacob had to work another seven years for Rachel. He loved Rachel more, and the sisters competed through their children. Jacob eventually had twelve sons and a daughter by four women.", ("Genesis",29)),
  C("Wrestling God", "Heading home to face Esau, Jacob wrestled all night with a man who was God. “I won’t let go unless you bless me.”",
    "The man touched Jacob’s hip and wrenched it, yet Jacob held on. He was renamed Israel — “he struggles with God.” He limped for the rest of his life. He named the place Peniel: “I saw God face to face, and yet my life was spared.”", ("Genesis",32)),
  C("Esau runs to him", "Jacob bowed seven times. Esau ran, embraced him, and wept. Twenty years of fear ended in forgiveness.",
    "Jacob said, “To see your face is like seeing the face of God.”", ("Genesis",33)),
  C("Grief and reunion", "Jacob believed his favorite son Joseph was dead for over 20 years — until he learned Joseph was ruling Egypt.",
    "He moved his whole family, 70 people, to Egypt during the famine. Before dying at 147, he blessed each of his sons; their families became the twelve tribes of Israel.", ("Genesis",46)),
 ]),
 dict(id="joseph-egypt", name="Joseph", role="Sold as a slave, became ruler of Egypt", art="joseph-reveals",
  facts=["Favorite son of Jacob", "The colorful coat", "Interpreted dreams"], cards=[
  C("The favorite", "Joseph was Jacob’s favorite son. His father gave him an ornate robe, and his brothers hated him.",
    "At 17 he also told on his brothers and shared dreams of their sheaves and the sun, moon and stars bowing to him. Even his father rebuked him.", ("Genesis",37)),
  C("Sold", "His brothers threw him into a dry well, then sold him to traders for 20 pieces of silver. They told Jacob a wild animal killed him.",
    "Reuben wanted to rescue him; Judah suggested selling instead of killing. They dipped the robe in goat’s blood. Jacob tore his clothes and refused to be comforted.", ("Genesis",37)),
  C("Potiphar’s house", "In Egypt Joseph was sold to Potiphar, an officer of Pharaoh, and rose to run his household — until Potiphar’s wife falsely accused him.",
    "She tried to seduce him day after day. He refused: “How could I do such a wicked thing and sin against God?” She grabbed his cloak; he ran, and she used it to frame him. He was thrown in prison.", ("Genesis",39)),
  C("Dreams in prison", "In prison Joseph interpreted the dreams of Pharaoh’s cupbearer and baker. Both came true — but the cupbearer forgot him for two years.",
    "Even in prison, the Lord was with him and the warden put him in charge. The cupbearer was restored, as Joseph predicted; the baker was executed.", ("Genesis",40)),
  C("Pharaoh’s dreams", "Pharaoh dreamed of seven fat cows eaten by seven thin ones. Joseph explained: seven years of plenty, then seven of famine.",
    "“I cannot do it,” Joseph said, “but God will give Pharaoh the answer.” He advised storing grain. Pharaoh put him in charge of all Egypt at age 30.", ("Genesis",41)),
  C("The brothers bow", "In the famine, Joseph’s brothers came to buy grain and bowed to him without recognizing him. Joseph tested them.",
    "He accused them of being spies, kept Simeon, and demanded they bring their youngest, Benjamin. When he framed Benjamin with a silver cup, Judah offered himself as a slave in Benjamin’s place — showing the brothers had changed.", ("Genesis",44)),
  C("“I am Joseph”", "Joseph wept so loudly the Egyptians heard. “I am Joseph! God sent me ahead of you to save lives.”",
    "He brought his father and family to live in Egypt. After Jacob died, the brothers feared revenge. Joseph said: “You intended to harm me, but God intended it for good, to accomplish the saving of many lives.” He died at 110, asking that his bones be carried back to the Promised Land — which Moses did.", ("Genesis",50)),
 ]),
])

cat("exodus", "Moses & the Promised Land", "Out of slavery and into the land God promised.", "red-sea", [
 dict(id="moses", name="Moses", role="The reluctant leader who led Israel out of Egypt", art="sinai",
  facts=["Raised in Pharaoh’s palace", "The burning bush", "Received the 10 Commandments"], cards=[
  C("Saved from the Nile", "Pharaoh ordered every Hebrew baby boy thrown into the Nile. Moses’ mother hid him in a basket in the reeds, and Pharaoh’s daughter adopted him.",
    "The Israelites had grown so numerous in Egypt that a new Pharaoh enslaved them and tried to control their numbers. Moses’ sister Miriam watched the basket and arranged for their own mother to nurse him. He grew up as a prince, educated in all the wisdom of Egypt.", ("Exodus",2)),
  C("Fugitive", "At 40, Moses killed an Egyptian who was beating a Hebrew slave. He fled to Midian and became a shepherd for 40 years.",
    "He thought no one saw — but the next day a Hebrew asked, “Are you thinking of killing me as you killed the Egyptian?” In Midian he defended seven sisters at a well, married one of them, Zipporah, and worked for her father Jethro.", ("Exodus",2)),
  C("The burning bush", "At 80, Moses saw a bush on fire that didn’t burn up. God spoke: “I am who I am. Go tell Pharaoh, ‘Let My people go.’”",
    "God told him to take off his sandals because he was on holy ground. Moses made excuse after excuse: Who am I? What’s Your name? What if they don’t believe me? I’m not a good speaker. Please send someone else. God gave him signs — a staff that became a snake — and sent his brother Aaron to speak for him.", ("Exodus",3)),
  C("Ten plagues", "Pharaoh refused, so God sent ten plagues: blood, frogs, gnats, flies, livestock disease, boils, hail, locusts, darkness, and death of the firstborn.",
    "Each plague struck at Egypt’s gods — the Nile, the sun, the livestock. Pharaoh kept promising to let them go, then hardening his heart. Before the last plague, Israelite families sacrificed a lamb and put its blood on their doorframes so death would pass over them — the first Passover.", ("Exodus",12)),
  C("The Red Sea", "Pharaoh chased the Israelites to the sea. Moses raised his staff, the water split, and Israel crossed on dry ground. The sea swallowed Egypt’s army.",
    "Moses told the terrified people, “The Lord will fight for you; you need only to be still.” A pillar of cloud stood between them and the Egyptians all night while a strong east wind divided the water. Afterward Moses and Miriam led the people in a song of victory.", ("Exodus",14)),
  C("Bread from heaven", "In the desert the people complained of hunger. God sent manna every morning and quail in the evening, and water from a rock.",
    "Manna appeared on the ground like frost — “What is it?” (man hu) gave it its name. It tasted like wafers made with honey, and it fed Israel for 40 years.", ("Exodus",16)),
  C("The Ten Commandments", "At Mount Sinai, amid thunder, fire and smoke, God gave the Ten Commandments, written on stone tablets.",
    "“I am the Lord your God, who brought you out of Egypt, out of the land of slavery. You shall have no other gods before Me.” The commandments cover worship of God, the Sabbath, honoring parents, and not murdering, committing adultery, stealing, lying or coveting. Moses also received instructions for the tabernacle, a portable tent where God’s presence would dwell among them.", ("Exodus",20)),
  C("The golden calf", "While Moses was on the mountain 40 days, the people made a golden calf. Moses smashed the tablets — then pleaded with God to forgive them.",
    "Moses even asked God to blot him out instead. God relented. Moses asked to see God’s glory; God hid him in a cleft of the rock and passed by, proclaiming, “The Lord, the compassionate and gracious God, slow to anger, abounding in love and faithfulness.” Moses’ face shone so brightly afterward that he wore a veil.", ("Exodus",32)),
  C("40 years in the wilderness", "When ten spies said Canaan was too strong to conquer, the people refused to go. God made them wander until that generation died.",
    "Moses’ own patience broke once: told to speak to a rock for water, he struck it angrily instead. Because of that, God said he would not enter the Promised Land.", ("Numbers",20)),
  C("How it ended", "At 120, Moses climbed Mount Nebo, saw the Promised Land, and died. God Himself buried him.",
    "His eyes were not weak nor his strength gone. Deuteronomy says no prophet has risen in Israel like Moses, “whom the Lord knew face to face.” Centuries later, Moses appeared with Elijah beside Jesus at the Transfiguration — finally standing in the Promised Land.", ("Deuteronomy",34)),
 ]),
 dict(id="aaron", name="Aaron", role="Moses’ brother and Israel’s first high priest", art="let-my-people-go",
  facts=["Moses’ older brother", "Spoke for Moses", "Made the golden calf"], cards=[
  C("The spokesman", "Moses said he couldn’t speak well, so God sent his older brother Aaron to speak for him.",
    "Aaron was three years older than Moses. He went with Moses before Pharaoh and threw down his staff, which became a snake and swallowed the Egyptian magicians’ snakes.", ("Exodus",7)),
  C("Holding up his arms", "When Israel fought the Amalekites, Aaron and Hur held up Moses’ tired arms so Israel would win.",
    "As long as Moses’ hands were raised, Israel was winning. When his arms got tired, they sat him on a stone and held his hands up until sunset.", ("Exodus",17)),
  C("The golden calf", "While Moses was on the mountain, Aaron gave in to the people and made a golden calf. He claimed it just came out of the fire.",
    "“They gave me the gold, and I threw it into the fire, and out came this calf!” It’s one of the weakest excuses in the Bible.", ("Exodus",32)),
  C("High priest", "God still chose Aaron and his sons as Israel’s priests. Aaron spoke the blessing still used today.",
    "“The Lord bless you and keep you; the Lord make His face shine on you and be gracious to you; the Lord turn His face toward you and give you peace.” When others challenged his priesthood, his staff sprouted, blossomed and produced almonds overnight. He died at 123 on Mount Hor.", ("Numbers",6)),
 ]),
 dict(id="miriam", name="Miriam", role="Prophet, songwriter and big sister", art="moses-nile",
  facts=["Sister of Moses & Aaron", "Watched over baby Moses", "Led the women in song"], cards=[
  C("Watching from the reeds", "Young Miriam watched baby Moses’ basket on the Nile, then offered to find a Hebrew nurse — their own mother.",
    "Her quick thinking meant Moses was raised by his mother in his earliest years, learning who he really was.", ("Exodus",2)),
  C("The song at the sea", "After the Red Sea, Miriam grabbed a tambourine and led the women in dancing: “Sing to the Lord, for He is highly exalted!”",
    "The Bible calls her a prophet — one of the first women given that title.", ("Exodus",15)),
  C("Jealousy", "Miriam and Aaron criticized Moses and his authority. God struck Miriam with a skin disease for a week; Moses prayed for her healing.",
    "The people waited for her before moving on. She died in Kadesh before Israel entered the land.", ("Numbers",12)),
 ]),
 dict(id="joshua", name="Joshua", role="The general who led Israel into the Promised Land", art="jericho",
  facts=["Moses’ assistant", "One of the 12 spies", "Jericho’s walls fell"], cards=[
  C("Moses’ assistant", "Joshua led Israel’s army against the Amalekites and went partway up Mount Sinai with Moses.",
    "He was Moses’ aide from his youth and would stay at the tent of meeting after Moses left. His name, Yehoshua, means “the Lord saves” — the same name as Jesus.", ("Exodus",17)),
  C("The faithful spy", "Of twelve spies sent into Canaan, only Joshua and Caleb said, “We can do it — the Lord is with us.”",
    "The people wanted to stone them. Because of their faith, they were the only adults of that generation allowed to enter the land.", ("Numbers",14)),
  C("Be strong and courageous", "When Moses died, God told Joshua three times: “Be strong and courageous… for the Lord your God will be with you wherever you go.”",
    "He was told to meditate on God’s law day and night.", ("Joshua",1)),
  C("Crossing the Jordan", "The river was at flood stage. When the priests carrying the Ark stepped in, the water stopped, and Israel crossed on dry ground.",
    "They set up twelve stones from the riverbed as a memorial so their children would ask, “What do these stones mean?”", ("Joshua",3)),
  C("Jericho", "Israel marched around Jericho for seven days, blew trumpets, and shouted — and the walls collapsed.",
    "Before the battle, Joshua met a man with a drawn sword: the commander of the Lord’s army, who told him to take off his sandals, just like Moses at the burning bush.", ("Joshua",6)),
  C("The sun stood still", "In a battle against five kings, Joshua prayed for the sun to stop. The day lasted until Israel won.",
    "“There has never been a day like it before or since, a day when the Lord listened to a human being.”", ("Joshua",10)),
  C("“As for me and my house”", "Before he died at 110, Joshua challenged Israel: “Choose this day whom you will serve. As for me and my house, we will serve the Lord.”",
    "The people promised to serve the Lord, and they did as long as Joshua and the elders who outlived him were alive.", ("Joshua",24)),
 ]),
 dict(id="caleb", name="Caleb", role="The spy who still wanted a mountain at 85", art=None,
  facts=["One of the 12 spies", "Believed God", "Fought giants at 85"], cards=[
  C("A different spirit", "When ten spies spread fear, Caleb silenced the people: “We should go up and take the land, for we can certainly do it.”",
    "God said Caleb had “a different spirit” and followed Him wholeheartedly.", ("Numbers",13)),
  C("“Give me this mountain”", "45 years later, at 85, Caleb asked for the hill country where the giants lived — and drove them out.",
    "“I am still as strong today as the day Moses sent me out.” He received Hebron as his inheritance.", ("Joshua",14)),
 ]),
 dict(id="rahab", name="Rahab", role="The outsider who hid the spies", art=None,
  facts=["Lived in Jericho’s wall", "Hid two Israelite spies", "Ancestor of Jesus"], cards=[
  C("Hiding the spies", "Rahab, a prostitute in Jericho, hid two Israelite spies under flax on her roof and misdirected the king’s men.",
    "Her house was built into the city wall. She told the spies, “I know that the Lord has given you this land… for the Lord your God is God in heaven above and on the earth below.” She’d heard about the Red Sea 40 years earlier.", ("Joshua",2)),
  C("The scarlet cord", "She let them down by a rope through her window. They told her to tie a scarlet cord there, and her family would be spared.",
    "When the walls fell, Joshua sent the two spies to bring out Rahab and her whole family.", ("Joshua",6)),
  C("Ancestor of kings", "Rahab married Salmon of Judah. Their son was Boaz, great-grandfather of King David — and she is named in Jesus’ family tree.",
    "Matthew’s genealogy includes her by name. Hebrews and James both praise her faith.", ("Matthew",1)),
 ]),
])
